var e={kind:`board`,caption:`同一套「先查缓存、没命中查数据库」的流程，看三种情况下数据库被查了几次`,stepTitles:{0:`① 正常读流程`,1:`② 缓存穿透`,2:`③ 缓存击穿`,3:`④ 缓存雪崩`,4:`⑤ 预热、更新与降级`},cols:3,regions:[{id:`req`,label:`请求`},{id:`cache`,label:`缓存`},{id:`db`,label:`数据库`}],legend:[[`ok`,`命中 / 挡住`],[`bad`,`未命中 / 压力`],[`new`,`写入`],[`hit`,`注意`]],frames:[{step:0,msg:`GET user:1`,calc:[[`先查缓存`,`没命中`],[`再查数据库`,`查到了，写回缓存再返回`]],note:`正常的读流程：先查 Redis，没命中再查数据库，查到后写回 Redis（带过期时间）再返回。`,boxes:{req:{items:[{t:`查 user:1`}]},cache:{items:[{t:`user:1：没有 → 未命中`,st:`bad`}],hot:!0,tag:`Redis`},db:{items:[{t:`SELECT … WHERE id = 1`,st:`hit`},{t:`写回 Redis（带过期时间）`,st:`new`}],hot:!0,tag:`这一步被查 1 次`}}},{step:0,msg:`GET user:1（再来一次）`,calc:[[`缓存命中`,`直接返回，数据库不用查`]],note:`下一次再查 user:1 就命中缓存了，数据库完全不用碰。下面三个问题，都是大量请求在这一步没命中、直接压到数据库上。`,boxes:{req:{items:[{t:`查 user:1`}]},cache:{items:[{t:`user:1 = {…}：命中`,st:`ok`}],hot:!0,tag:`Redis`},db:{items:[],tag:`这一步被查 0 次`}}},{step:1,msg:`GET user:-1 × 5`,calc:[[`缓存穿透`,`查的是根本不存在的数据`],[`后果`,`5 次全部打到数据库；被人用随机 id 刷接口时就是成千上万`]],note:`缓存穿透：查的是数据库里根本不存在的数据（比如 id = -1，或者有人用随机 id 刷接口）。查不到就不会写缓存，于是每次都打到数据库。`,boxes:{req:{items:[{t:`5 个请求查 id = -1`,st:`hit`}],hot:!0},cache:{items:[{t:`永远没有 → 每次都未命中`,st:`bad`}],tag:`Redis`},db:{items:[{t:`每次都查一遍，每次都查不到`,st:`bad`}],hot:!0,tag:`这一步被查 5 次`}}},{step:1,msg:`方案一：把「查不到」也缓存起来`,calc:[[`第一次`,`数据库查不到 → 缓存一个空值，几分钟过期`],[`后面几次`,`命中空值，直接返回`]],note:`把「查不到」也缓存成空值，过期时间设短一些。这样 5 个请求只有第一个查了数据库。缺点：随机 id 每个都不同，空值会占满缓存。`,boxes:{req:{items:[{t:`5 个请求查 id = -1`}]},cache:{items:[{t:`user:-1 = 空值（过期时间设短）`,st:`new`}],hot:!0,tag:`Redis`},db:{items:[{t:`只在第一次被查`,st:`ok`}],tag:`这一步被查 1 次`}}},{step:1,msg:`方案二：布隆过滤器挡在最前面`,calc:[[`布隆过滤器说「不存在」`,`一定不存在，直接拦掉`],[`说「存在」`,`可能误判（例如这里的 1004），放行后由数据库兜底`],[`另外`,`删不了元素；还要配合参数校验和限流`]],note:`在缓存前加布隆过滤器：先把所有存在的 id 放进去（每个 id 用 3 个哈希函数把位数组的 3 个位置成 1）。查询时只要有一位是 0，就一定不存在，直接拦掉；3 位都是 1 也只是「可能存在」—— 这里 1004 就被误判了，但误判只会多查一次数据库，不会漏掉真实数据。`,boxes:{req:{items:[{t:`查 id = -1`},{t:`查 id = 1004`,st:`hit`}]},cache:{items:[{t:`布隆过滤器：256 位、3 个哈希，放入 id 1～40`},{t:`-1 → 有一位是 0 → 一定不存在，拦掉`,st:`ok`},{t:`1004 → 3 位都是 1 → 「可能存在」（误判）`,st:`hit`}],hot:!0,tag:`布隆过滤器`},db:{items:[],tag:`这一步被查 0 次`}}},{step:2,msg:`热点 key product:1 刚过期，100 个请求同时到达`,calc:[[`缓存击穿`,`一个热点 key 过期的瞬间被打穿`],[`后果`,`100 次回源，数据库瞬间压力暴涨`]],note:`缓存击穿：某一个访问量极高的热点 key 恰好过期，那一瞬间大量请求同时没命中，一起去查数据库、重建缓存。`,boxes:{req:{items:[{t:`100 个并发请求`,st:`hit`}],hot:!0},cache:{items:[{t:`product:1：刚过期 → 全部未命中`,st:`bad`}],tag:`Redis`},db:{items:[{t:`100 个请求同时查数据库、同时重建缓存`,st:`bad`}],hot:!0,tag:`这一步被查 100 次`}}},{step:2,msg:`方案：互斥锁，只让一个请求回源`,calc:[[`抢锁`,`SET key value NX PX：只有一个能成功`],[`其他请求`,`稍等片刻重读缓存，命中新值`],[`另一种`,`不设过期，value 里记逻辑过期时间，后台异步刷新、先返回旧值`]],note:`互斥锁：只让抢到锁的一个请求回源重建，其余 99 个稍等后重读缓存。数据库只被查 1 次。也可以让热点 key 不过期，value 里记一个逻辑过期时间，由后台线程异步刷新。`,boxes:{req:{items:[{t:`1 个抢到锁 → 回源`,st:`ok`},{t:`99 个没抢到 → 稍等后重读缓存`,st:`hit`}],hot:!0},cache:{items:[{t:`SET lock:product:1 … NX PX 3000`,st:`new`},{t:`重建后 product:1 = {…}`,st:`ok`}],hot:!0,tag:`Redis`},db:{items:[{t:`只被查 1 次`,st:`ok`}],tag:`这一步被查 1 次`}}},{step:3,msg:`1000 个 key 同时写入、过期时间都是 3600 秒`,calc:[[`缓存雪崩`,`大量 key 同一时间过期，或 Redis 整个宕机`],[`后果`,`大面积请求同时落到数据库，数据库被压垮后连锁拖垮整个系统`]],note:`缓存雪崩：比如批量预热时 1000 个 key 用了同样的过期时间，一小时后在同一秒全部过期；或者 Redis 整个宕机。大面积请求同时压到数据库上。`,boxes:{req:{items:[{t:`3600 秒后，大量请求同时到达`,st:`hit`}],hot:!0},cache:{items:[{t:`1000 个 key 在同一秒全部过期`,st:`bad`}],tag:`Redis`},db:{items:[{t:`那一秒回源 1000 次`,st:`bad`}],hot:!0,tag:`这一步被查 1000 次`}}},{step:3,msg:`方案：过期时间加随机值打散`,calc:[[`打散过期时间`,`同一秒最多 7 次回源（原来 1000 次）`],[`Redis 宕机`,`做高可用：哨兵或 Cluster`],[`兜底`,`数据库前限流降级；应用里加一层本地缓存`]],note:`过期时间加上随机值，1000 个 key 的过期时刻被打散到 497 个不同的秒，最忙的一秒也只回源 7 次。针对 Redis 整体宕机，要靠哨兵或 Cluster 做高可用，再在数据库前限流降级。`,boxes:{req:{items:[{t:`请求陆续到达`}]},cache:{items:[{t:`过期时间 = 3600 + 随机 0～600 秒`,st:`new`},{t:`分散到 497 个不同的秒`,st:`ok`}],hot:!0,tag:`Redis`},db:{items:[{t:`最忙的一秒只回源 7 次`,st:`ok`}],hot:!0,tag:`这一步被查 7 次`}}},{step:4,msg:`预热 / 更新 / 降级`,calc:[[`预热`,`上线前把热点数据加载进缓存，避免刚启动全部未命中`],[`更新`,`Cache Aside：先更新数据库再删缓存，过期时间兜底`],[`降级`,`非核心功能返回默认值或兜底数据，保住核心链路`]],note:`配套手段：预热，上线前或启动时把热点数据提前加载进缓存；更新，用 Cache Aside（先更新数据库再删缓存）；降级，Redis 或下游出故障时，非核心功能直接返回默认值或「稍后再试」，而不是让所有请求都去压数据库。演示结束。`,boxes:{req:{items:[{t:`上线后的第一批请求`},{t:`Redis 故障时的非核心请求`,st:`hit`}]},cache:{items:[{t:`启动时预热：热点数据提前加载`,st:`ok`},{t:`更新：先更新数据库，再删缓存`,st:`new`}],hot:!0,tag:`Redis`},db:{items:[{t:`预热后第一批请求不回源`,st:`ok`},{t:`降级：直接返回默认值 / 稍后再试`,st:`hit`}],hot:!0,tag:`这一步被查 0 次`}}}]};export{e as default};